      const afterHouseholdBudget = afterBills != null && itemSpend != null
        ? roundCent(afterBills - budget.hold - itemSpend.cents / 100) : null;
      const budgetHoldTermTrust = typeof budget.hold === 'number' && Number.isFinite(budget.hold)
