        spendingCycleLabel,
        spendingCycle: planUnavailable ? null : budget.spendingCycle,
        cycleUnresolved: budget.cycleUnresolved === true,
        operatingPlanUnavailable: planUnavailable,
        operatingPlanNote: planUnavailable
